/**
 * @name Insecure use of eval/exec
 * @description Detects use of eval or exec on potentially untrusted data
 * @kind path-problem
 * @problem.severity error
 * @id py/insecure-eval-exec
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module EvalExecConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // Match calls to the built-in eval or exec functions
      call = API::builtin(["eval", "exec"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module EvalExecFlow = TaintTracking::Global<EvalExecConfig>;
import EvalExecFlow::PathGraph

from EvalExecFlow::PathNode source, EvalExecFlow::PathNode sink
where EvalExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches eval/exec here.", source, "user input"
